# 견본5 Claude 담당 10·12·14·16번 (10번 4.4점, 12번 4.5점, 14번 4.7점, 16번 4.9점)
ITEMS = {
  10: dict(body=r"""실수 전체의 집합에서 증가하는 연속함수 \(f(x)\)가 다음 조건을 만족시킬 때, 함수 \(y=f(x)\)의 그래프와 \(x\)축 및 두 직선 \(x=4\), \(x=8\)로 둘러싸인 부분의 넓이는?""",
           cond=[('가', r"모든 실수 \(x\)에 대하여 \(f(x)=f(x-2)+3\)이다."),
                 ('나', r"\(\displaystyle\int_1^5 f(x)\,dx=0\)")],
           choices=['21', '18', '15', '12', '9'],
           ans=2,
           key='J60', src='2019학년도 수능 나형 17번',
           var=r"[조건 변경] \(f(x)=f(x-3)+4\), \(\int_0^6f=0\) → \(f(x)=f(x-2)+3\), \(\int_1^5f=0\) (블록 경계가 \(1\), \(3\), \(5\)) · [구하는 대상 변경] 블록과 맞는 구간 \([6,\,9]\) → 블록과 \(1\)만큼 어긋난 구간 \([4,\,8]\): 시작점이 \(1\) 커지면 길이 \(2\)인 구간의 적분이 \(3\)씩 커진다는 관계로 바꿈(분석집 방향 1) · [함정 추가] \(f&gt;0\)을 보이려면 새로 얻은 \(\int_2^4f=0\)에서 \(f(4)&gt;0\)을 끌어내야 함(\(\int_1^5f=0\)만으로는 \(f(5)&gt;0\)만 바로 보임)",
           level='중상',
           sol=r"(가)에서 모든 실수 \(t\)에 대하여 \(\displaystyle\int_{t+2}^{t+3}f(x)\,dx=\int_t^{t+1}f(x+2)\,dx=\int_t^{t+1}\{f(x)+3\}\,dx=\int_t^{t+1}f(x)\,dx+3\)이다. \(\displaystyle G(t)=\int_t^{t+2}f(x)\,dx\)라 하면 \(\displaystyle G(t+1)-G(t)=\int_{t+2}^{t+3}f(x)\,dx-\int_t^{t+1}f(x)\,dx=3\)이다. (나)에서 \(G(1)+G(3)=G(1)+\{G(1)+6\}=0\)이므로 \(G(1)=-3\)이고, \(G(2)=0\), \(G(4)=6\), \(G(6)=12\)이다. \(\displaystyle G(2)=\int_2^4f(x)\,dx=0\)이고 \(f(x)\)는 증가하는 연속함수이므로 \(f(4)&gt;0\)이다. (\(f(4)\le0\)이면 \(2\le x&lt;4\)에서 \(f(x)&lt;0\)이 되어 \(\int_2^4f(x)\,dx&lt;0\)이다.) 따라서 \(4\le x\le8\)에서 \(f(x)&gt;0\)이고, 구하는 넓이는 \(\displaystyle\int_4^8f(x)\,dx=G(4)+G(6)=6+12=18\)이다.",
           fast=r"\(\displaystyle G(t)=\int_t^{t+2}f\)이면 \(G'(t)=f(t+2)-f(t)=3\)이므로 \(G(t)=3t+k\). (나) \(G(1)+G(3)=0\)에서 \(G(t)=3t-6\). \(G(2)=0\)이라 \(f(4)&gt;0\), 넓이는 \(G(4)+G(6)=18\).",
           note=r"원본은 적분 구간 \([0,\,6]\)과 구하는 구간 \([6,\,9]\)가 같은 블록 경계 위에 있었지만, 여기서는 구하는 구간이 블록과 \(1\)만큼 어긋나 시작점을 옮길 때의 적분 변화(\(3\))를 써야 하고, 부호 판정도 새로 얻은 \(\int_2^4f=0\)으로 한다.",
           wrong=r"구간을 \(1\)만큼 옮길 때 전체 적분이 \(3\)만 줄어든다고 보아 \(\int_5^9f-3=24-3\)에서 \(21\)(①), 블록 경계에 맞춘 \([3,\,7]\)로 계산하거나 두 블록에서 각각 \(6\)씩 줄인다고 보면 \(12\)(④), 원본 함정처럼 길이 \(2\)인 블록의 적분이 \(6\)이 아니라 \(3\)씩 커진다고 보면 \(G(1)=-\frac32\)에서 \(9\)(⑤)",
           author='claude'),

  12: dict(body=r"""실수 \(a\)에 대하여 점 \((1,\ a)\)에서 곡선 \(y=x^4-6x^2+6x\)에 그은 서로 다른 접선의 개수를 \(f(a)\)라 할 때, 함수 \(f(a)\)가 불연속이 되도록 하는 모든 \(a\)의 값의 합은?""",
           choices=['14', '15', '16', '17', '18'],
           ans=1,
           key='M29', src='2023년 수능특강 [23009-0120]',
           var=r"[구조 변경] 삼차곡선 \(y=x^3-x\) → 사차곡선 \(y=x^4-6x^2+6x\): 서로 다른 두 점에서 접하는 직선 \(y=6x-9\)가 있어 접점은 \(2\)개인데 접선은 \(1\)개인 \(a=-3\)이 생김(접점 수 \(\ne\) 접선 수) · [함정 추가] \(x=1\)이 변곡점이라 접점 방정식 \(a=h(t)\)의 도함수가 \((t-1)^2\)을 인수로 가져 \(t=1\)은 극값이 아님: 삼차곡선의 TIP '곡선과 변곡점 접선의 높이가 경계'를 그대로 쓰면 \(a=1\)을 넣게 됨 · 점 \((1,\ a)\)와 질문 틀은 유지",
           level='중상',
           sol=r"곡선 위의 점 \((t,\ t^4-6t^2+6t)\)에서의 접선의 방정식은 \(y=(4t^3-12t+6)(x-t)+t^4-6t^2+6t\)이고, 이 직선이 점 \((1,\ a)\)를 지나면 \(a=-3t^4+4t^3+6t^2-12t+6\)이다. 이 식의 우변을 \(h(t)\)라 하면 \(h'(t)=-12t^3+12t^2+12t-12=-12(t-1)^2(t+1)\)이므로 \(h(t)\)는 \(t\le-1\)에서 증가하고 \(t\ge-1\)에서 감소하며 최댓값은 \(h(-1)=17\)이다. 따라서 방정식 \(h(t)=a\)의 서로 다른 실근의 개수는 \(a&lt;17\)일 때 \(2\), \(a=17\)일 때 \(1\), \(a&gt;17\)일 때 \(0\)이다. 한편 서로 다른 두 점 \(x=p\), \(x=q\)에서 곡선에 접하는 직선 \(y=mx+n\)이 있으면 \(x^4-6x^2+6x-(mx+n)=(x-p)^2(x-q)^2\)이고, 양변의 \(x^3\), \(x^2\)의 계수를 비교하면 \(p+q=0\), \(p^2=3\)이므로 이 직선은 \(x^4-6x^2+6x-(6x-9)=(x^2-3)^2\)에서 \(y=6x-9\) 하나뿐이다. 이 직선은 점 \((1,\ -3)\)을 지나므로 \(a=-3\)일 때 두 접점 \(t=-\sqrt3\), \(t=\sqrt3\)에서의 접선은 같은 직선이다. 그러므로 \(f(a)=2\) \((a&lt;17,\ a\ne-3)\), \(f(-3)=1\), \(f(17)=1\), \(f(a)=0\) \((a&gt;17)\)이고, \(f(a)\)가 불연속이 되는 \(a\)의 값은 \(-3\), \(17\)이다. 따라서 구하는 합은 \(14\)이다.",
           fast=r"\(h(t)=-3t^4+4t^3+6t^2-12t+6\), \(h'=-12(t-1)^2(t+1)\)이므로 극값은 \(h(-1)=17\)뿐(\(t=1\)은 극값 아님). 사차곡선이라 두 점에서 접하는 직선을 확인: \(x^4-6x^2+6x-(6x-9)=(x^2-3)^2\)이고 \(y=6x-9\)는 \((1,\ -3)\)을 지나므로 \(a=-3\)에서 접선이 \(1\)개 → \(-3+17=14\).",
           note=r"원본은 접점 방정식 \(a=-2t^3+3t^2-1\)의 두 극값 \(-1\), \(0\)만 보면 되었지만, 여기서는 사차곡선이라 극값이 \(t=-1\)의 \(17\) 하나뿐이고(\(t=1\)은 도함수의 중근), 대신 두 점에서 접하는 직선 \(y=6x-9\) 때문에 접점 수(\(2\))와 접선 수(\(1\))가 다른 \(a=-3\)에서 불연속이 생긴다.",
           wrong=r"두 점에서 접하는 직선을 빠뜨리면 \(17\)(④), 삼차곡선처럼 변곡점 \(x=1\)의 높이 \(1\)을 경계로 넣으면 \(-3+17+1=15\)(②), 둘 다 하면 \(17+1=18\)(⑤)",
           author='claude'),

  14: dict(body=r"""시각 \(t=0\)일 때 동시에 원점을 출발하여 수직선 위를 움직이는 두 점 \(\mathrm{P}\), \(\mathrm{Q}\)의 시각 \(t\) \((t\ge0)\)에서의 속도가 각각
\[v_1(t)=3t^2-12t+9,\quad v_2(t)=6t-6\]
이다. 시각 \(t\)에서의 두 점 \(\mathrm{P}\), \(\mathrm{Q}\) 사이의 거리를 \(f(t)\)라 할 때, 함수 \(f(t)\)는 \(t=a\)와 \(t=b\)에서 극대이다. 시각 \(t=a\)에서 \(t=b\)까지 점 \(\mathrm{P}\)가 움직인 거리는?""",
           choices=['16', '20', '24', '28', '32'],
           ans=3,
           key='J25', src='학교 자체 출제',
           var=r"[자체 출제, 가장 가까운 유형 J25] 거리 \(f(t)\)의 증감 구간 제시 → '\(t=a\), \(t=b\)에서 극대': 위치의 차 \(x_{\mathrm P}-x_{\mathrm Q}=t^3-9t^2+15t\)의 극솟값이 음수(\(-25\))라 그 시각 \(t=5\)가 거리의 극대가 됨(분석집 방향 1) · [함정 추가] \([1,\,5]\) 안에서 점 \(\mathrm P\)의 속도 \(3(t-1)(t-3)\)이 \(t=3\)에서 부호가 바뀜(상대운동의 전환점과 개별 방향 전환점 구분) · [함수 교체] 위치의 차 \(\frac13t(t-6)^2\) → 극댓값은 양수, 극솟값은 음수인 \(t^3-9t^2+15t\)",
           level='중상',
           sol=r"두 점 \(\mathrm{P}\), \(\mathrm{Q}\)의 시각 \(t\)에서의 위치를 각각 \(x_1\), \(x_2\)라 하면 \(\displaystyle x_1=\int_0^t(3s^2-12s+9)\,ds=t^3-6t^2+9t\), \(\displaystyle x_2=\int_0^t(6s-6)\,ds=3t^2-6t\)이다. \(D(t)=x_1-x_2=t^3-9t^2+15t\)라 하면 \(f(t)=|D(t)|\)이다. \(D'(t)=3t^2-18t+15=3(t-1)(t-5)\)이므로 \(D(t)\)는 \(0\le t\le1\)에서 증가, \(1\le t\le5\)에서 감소, \(t\ge5\)에서 증가하고 \(D(0)=0\), \(D(1)=7\), \(D(5)=-25\)이다. \(D(1)&gt;0&gt;D(5)\)이므로 \(D(t_1)=0\)인 \(t_1\) \((1&lt;t_1&lt;5)\)과 \(D(t_2)=0\)인 \(t_2\) \((t_2&gt;5)\)가 있고, \(f(t)\)는 \([0,\,1]\)에서 증가, \([1,\,t_1]\)에서 감소, \([t_1,\,5]\)에서 증가, \([5,\,t_2]\)에서 감소, \([t_2,\,\infty)\)에서 증가한다. 따라서 \(f(t)\)는 \(t=1\)과 \(t=5\)에서 극대이므로 \(a=1\), \(b=5\) (또는 그 반대)이다. 점 \(\mathrm{P}\)의 속도 \(v_1(t)=3(t-1)(t-3)\)은 \(1&lt;t&lt;3\)에서 음수, \(3&lt;t&lt;5\)에서 양수이므로 구하는 거리는 \(\displaystyle\int_1^5|v_1(t)|\,dt=\{x_1(1)-x_1(3)\}+\{x_1(5)-x_1(3)\}=(4-0)+(20-0)=24\)이다.",
           fast=r"\(v_1-v_2=3(t-1)(t-5)\)이고 위치의 차가 \(t=1\)에서 \(7&gt;0\), \(t=5\)에서 \(-25&lt;0\)이므로 거리는 \(t=1\), \(t=5\)에서 극대. \(x_1=t(t-3)^2\)에서 \(x_1(1)=4\), \(x_1(3)=0\), \(x_1(5)=20\) → \(4+20=24\).",
           note=r"원형 J25는 위치의 차 \(\frac13t(t-6)^2\)가 \(0\) 이상이라 거리의 증감이 위치의 차의 증감과 같았지만, 여기서는 위치의 차의 극솟값이 음수라 그 시각이 거리의 극대가 되고, 두 극대 시각 사이에서 점 \(\mathrm P\)가 운동 방향을 바꾼다.",
           wrong=r"움직인 거리 대신 위치의 변화량 \(x_1(5)-x_1(1)=16\)(①), \(t=5\)에서의 위치 \(20\) 또는 \(t=3\) 뒤의 거리만 쓰면 \(20\)(②), 두 점 사이의 거리의 변화 \(f(1)+f(5)=7+25\)를 쓰면 \(32\)(⑤)",
           author='claude'),

  16: dict(body=r"""상수 \(a\)와 이차함수 \(f(x)\)에 대하여 함수
\[g(x)=\begin{cases}2x^3+ax^2+24x+36 & (x\le0)\\ f(x) & (x&gt;0)\end{cases}\]
가 다음 조건을 만족시킬 때, \(g(-2)+g(2)\)의 값은?""",
           cond=[('가', r"함수 \(g(x)\)는 실수 전체의 집합에서 미분가능하다."),
                 ('나', r"\(x\)에 대한 방정식 \(g'(x)\times g'(-2x)=0\)의 서로 다른 실근의 개수는 \(4\)이다."),
                 ('다', r"\(x&gt;0\)에서 함수 \(g(x)\)의 최댓값은 \(72\)이다.")],
           choices=['84', '88', '92', '96', '100'],
           ans=2,
           key='M66', src='2025학년도 수능 15번',
           var=r"[조건 변경] \(g'(x)\times g'(x-4)=0\)의 실근 \(4\)개(평행이동, 간격 \(4\)의 사슬) → \(g'(x)\times g'(-2x)=0\)의 실근 \(4\)개(부호를 바꾼 배율: \(x\le0\)의 근과 \(x&gt;0\)의 근이 서로 겹쳐야 함) · [함수 교체] \(x^3+ax^2+15x+7\) → \(2x^3+ax^2+24x+36\), '최고차항의 계수가 음수' 대신 (다) \(x&gt;0\)에서의 최댓값 \(72\)로 \(f\)를 먼저 결정 · [함정 추가] 원본은 \(a\ne3\sqrt5\)로 중근을 뺐지만, 여기서는 사슬이 근과 계수의 관계(두 근의 곱 \(4\))에 막혀 중근인 경우(\(a=12\))만 남음: 원본처럼 사슬을 만들면 \(a=15\)",
           level='상',
           sol=r"(가)에서 \(g(x)\)는 \(x=0\)에서 연속이고 미분가능하므로 \(f(0)=36\), \(f'(0)=24\)이다. \(f(x)=-px^2+24x+36\) \((p\ne0)\)으로 놓으면, \(x&gt;0\)에서 최댓값이 있으므로 \(p&gt;0\)이고 \(f(x)=-p\left(x-\dfrac{12}p\right)^2+36+\dfrac{144}p\)이다. (다)에서 \(36+\dfrac{144}p=72\)이므로 \(p=4\), \(f(x)=-4x^2+24x+36\)이다. 따라서 \(g'(x)=6x^2+2ax+24\) \((x\le0)\), \(g'(x)=-8x+24\) \((x&gt;0)\)이다. 방정식 \(g'(x)=0\)의 실근의 집합을 \(A\)라 하면 \(g'(-2x)=0\)의 실근의 집합은 \(B=\left\{-\dfrac{\alpha}2\,\middle|\,\alpha\in A\right\}\)이고, (나)는 \(A\cup B\)의 원소의 개수가 \(4\)라는 뜻이다. \(x&gt;0\)에서 \(g'(x)=0\)의 근은 \(3\)뿐이므로 \(3\in A\), \(-\dfrac32\in B\)이다. 이차방정식 \(6x^2+2ax+24=0\)의 두 근의 곱은 \(4\)이므로 두 근은 부호가 같다. (i) \(x\le0\)에서 서로 다른 두 실근 \(\alpha\), \(\beta\)를 가질 때, \(A=\{\alpha,\ \beta,\ 3\}\), \(B=\left\{-\dfrac\alpha2,\ -\dfrac\beta2,\ -\dfrac32\right\}\)이다. 음수끼리, 양수끼리만 같을 수 있으므로 겹치는 경우는 \(-\dfrac32\in\{\alpha,\ \beta\}\) 또는 \(3\in\left\{-\dfrac\alpha2,\ -\dfrac\beta2\right\}\), 즉 \(-6\in\{\alpha,\ \beta\}\)뿐이다. 원소가 \(4\)개이려면 두 경우가 모두 일어나야 하므로 \(\{\alpha,\ \beta\}=\left\{-6,\ -\dfrac32\right\}\)인데 \(\alpha\beta=9\ne4\)이므로 모순이다. (ii) 중근 \(\alpha\)를 가질 때, \(\alpha^2=4\), \(\alpha&lt;0\)에서 \(\alpha=-2\), \(a=12\)이고 \(A=\{-2,\ 3\}\), \(B=\left\{1,\ -\dfrac32\right\}\)이므로 원소는 \(4\)개이다. (iii) \(x\le0\)에서 실근이 없을 때, \(A=\{3\}\), \(B=\left\{-\dfrac32\right\}\)이므로 원소는 \(2\)개이다. 따라서 \(a=12\)이고 \(g(-2)=-16+48-48+36=20\), \(g(2)=f(2)=-16+48+36=68\)이므로 \(g(-2)+g(2)=88\)이다.",
           fast=r"(가)(다)에서 \(f=-4x^2+24x+36\), \(x&gt;0\)의 근 \(3\). 원본처럼 사슬로 두 번 겹치려면 \(x\le0\)의 두 근이 \(-\frac32\), \(-6\)이어야 하는데 곱이 \(4\)가 아니라 불가 → 중근 \(-2\) \((a=12)\): \(\{-2,\ 3\}\cup\{1,\ -\frac32\}\)로 \(4\)개 → \(20+68=88\).",
           note=r"원본은 \(g'(x)\)의 근과 그것을 \(4\)만큼 옮긴 근이 간격 \(4\)의 사슬 \(-5\), \(-1\), \(3\)을 이루고 \(a\ne3\sqrt5\)로 중근을 뺐지만, 여기서는 \(g'(-2x)\)로 바꿔 \(x\le0\)의 근과 \(x&gt;0\)의 근이 서로 겹쳐야 하고, (다)로 오른쪽 근이 \(3\)으로 먼저 정해져 사슬이 근과 계수의 관계에 막히므로 오히려 중근인 경우만 남는다.",
           wrong=r"(다)를 쓰지 않고 원본처럼 사슬 \(-4\), \(-1\), \(2\)를 만들면 \(a=15\), \(f(x)=-6x^2+24x+36\)에서 \(32+60=92\)(③, \(g'(-x)\)로 착각해 \(a=13\)을 택해도 \(24+68=92\)), (다)에서 상수항 \(36\)을 빼지 않고 \(\frac{144}p=72\)로 \(p=2\)를 구하면 \(20+76=96\)(④), 사슬의 \(a=15\)에 (다)의 \(f\)를 섞으면 \(32+68=100\)(⑤)",
           author='claude'),
}
